/*
 * A380372  Characteristic function of A082851.
 * https://oeis.org/A380372
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 9371, u16 n <= 9371, u32 n <= 9371, u64 n <= 9371,
 *            u128 n <= 9371, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Algorithm: return 1 iff the n‑th term of the infinite
 * sequence S(k) generated by
 *   S(0) = {}
 *   S(k) = S(k‑1) S(k‑1) 0^(k‑1) 1
 * contains a final 1 of a run; otherwise return 0.
 * The function works for any idx_t >= 1 and is O(log n). */

#include <stdlib.h>
#include <stdint.h>

/* Persistent cache of |S(k)| values.  len_cache[0] = 0. */
static idx_t *len_cache = NULL;          /* indices 0 … */
static size_t len_cap   = 0;              /* capacity of len_cache        */

/* Ensure len_cache contains |S(i)| up to the smallest i with |S(i)| ≥ n. */
static void ensure_len(idx_t n)
{
    if (len_cache == NULL) {
        len_cap   = 4;
        len_cache = (idx_t *)malloc(len_cap * sizeof(idx_t));
        len_cache[0] = 0;
    }

    size_t k = 0;
    while (len_cache[k] < n) {
        /* Grow the cache if necessary. */
        if (k + 1 >= len_cap) {
            len_cap *= 2;
            len_cache = (idx_t *)realloc(len_cache, len_cap * sizeof(idx_t));
        }
        ++k;
        /* |S(k)| = 2·|S(k‑1)| + k; use 128‑bit arithmetic to avoid overflow. */
        unsigned __int128 val = (unsigned __int128)len_cache[k - 1] * 2 + k;
        if (val > (unsigned __int128)UINT64_MAX)
            len_cache[k] = UINT64_MAX;
        else
            len_cache[k] = (idx_t)val;
    }
}

/* Recursive helper: returns a(n) for the sequence S(k) that contains position n. */
static seq_t rec_get(idx_t n, size_t k)
{
    if (k == 1)          /* S(1) = {1} */
        return (seq_t)1;

    idx_t half = len_cache[k - 1];

    if (n <= half)
        return rec_get(n, k - 1);
    else if (n <= half + half)
        return rec_get(n - half, k - 1);
    else {
        idx_t pos = n - 2 * half;   /* 1‑based index inside the run of length k */
        return (pos == k) ? (seq_t)1 : (seq_t)0;
    }
}

/* Public entry point required by the framework. */
seq_t a(idx_t n)
{
    if (n == 0)                /* undefined for the offset 1; return 0 as a safe default */
        return (seq_t)0;

    ensure_len(n);

    /* Find minimal k with |S(k)| ≥ n. */
    size_t k = 0;
    while (len_cache[k] < n)
        ++k;

    return rec_get(n, k);
}
